diff --git a/test/agent/finalize_gate_test.dart b/test/agent/finalize_gate_test.dart
index f6687e9f01..02c78b6cad 100644
--- a/test/agent/finalize_gate_test.dart
+++ b/test/agent/finalize_gate_test.dart
@@ -364,23 +364,51 @@ void main() {
       expect(contract, contains('request_secret'));
     });

-    test('gh-1605/gh-1652: documents the grader-parity step (2.5, not a named check)', () {
-      // The verifier runs produced entry points itself — a fresh
-      // subprocess from a different working directory with a clean env —
-      // so an in-session pass proves nothing about what the grader sees.
-      // The checklist must pin the parity re-run and its outcome:
-      // divergence is a `fail` ledger item, never a silent pass.
-      expect(contract, contains('Grader parity'));
-      expect(contract, contains('different working directory'));
-      expect(contract, contains('clean env'));
-      expect(contract, contains('fresh subprocess'));
-      expect(contract, contains('relative paths'));
-      expect(contract, contains('divergence'));
-      // gh-1652 C1: the check is a NUMBERED step (2.5) inside the loop
-      // — between verify and fix — not a named-checks bullet; flash
-      // executes numbered steps but skimmed the bullet list.
-      expect(contract, contains('2.5. **Grader parity**'));
-      expect(contract, isNot(contains('- **Grader parity**')));
+    test(
+      'gh-1605/gh-1652: documents the grader-parity step (2.5, not a named check)',
+      () {
+        // The verifier runs produced entry points itself — a fresh
+        // subprocess from a different working directory with a clean env —
+        // so an in-session pass proves nothing about what the grader sees.
+        // The checklist must pin the parity re-run and its outcome:
+        // divergence is a `fail` ledger item, never a silent pass.
+        expect(contract, contains('Grader parity'));
+        expect(contract, contains('different working directory'));
+        expect(contract, contains('clean env'));
+        expect(contract, contains('fresh subprocess'));
+        expect(contract, contains('relative paths'));
+        expect(contract, contains('divergence'));
+        // gh-1652 C1: the check is a NUMBERED step (2.5) inside the loop
+        // — between verify and fix — not a named-checks bullet; flash
+        // executes numbered steps but skimmed the bullet list.
+        expect(contract, contains('2.5. **Grader parity**'));
+        expect(contract, isNot(contains('- **Grader parity**')));
+      },
+    );
+
+    test('gh-1834: conformance claims count as verified only with negative '
+        '+ combination checks (AC1/AC2), taught abstractly', () {
+      // AC1 — a "verified" conformance item counts only with negative and
+      // combination checks (rejected incompatible options, empty/corrupt
+      // inputs, boundary values, must-NOT-work cases); a blanket
+      // "everything matches" is not verified.
+      expect(contract, contains('2.6. **Conformance coverage**'));
+      expect(contract, contains('negative and combination checks'));
+      expect(contract, contains('empty and corrupt inputs'));
+      expect(contract, contains('boundary values'));
+      expect(contract, contains('"must NOT work"'));
+      expect(contract, contains('without such coverage is not verified'));
+      // AC2 — the general principle rides an abstract example, and no
+      // benchmark/task/flag names leak into the model-facing prompt.
+      expect(contract, contains('certifies nothing about rejection paths'));
+      expect(contract, contains('well-formed'));
+      for (final banned in ['terminal-bench', 'harbor', 'gh-18']) {
+        expect(contract, isNot(contains(banned)), reason: banned);
+      }
+      // AC3 — tasks with no conformance claim see no gate change: the
+      // step is explicitly conditional, never a new unconditional
+      // requirement.
+      expect(contract, contains('applies ONLY when'));
     });

     test('mandates command-verified state, never memory', () {
diff --git a/test/cli/finalize_gate_prompt_test.dart b/test/cli/finalize_gate_prompt_test.dart
index 5bcbeb510f..a97fe743d5 100644
--- a/test/cli/finalize_gate_prompt_test.dart
+++ b/test/cli/finalize_gate_prompt_test.dart
@@ -119,6 +119,87 @@ void main() {
     );
   });

+  test('gh-1834 C1: conformance coverage is a numbered step (2.6) between '
+      'grader parity and fix', () {
+    // The self-certification blind spot: a run declared "behavioral
+    // parity confirmed" off a happy-path-only suite; the external
+    // evaluation then failed exactly the unprobed branches — mutually
+    // exclusive option pairs never rejected, "must error" inputs never
+    // run. The gate must make negative + combination coverage a
+    // NUMBERED step (flash executes numbered steps, skims the bullet
+    // list — gh-1652).
+    expect(
+      finalizeGateContractPrompt,
+      contains('2.6. **Conformance coverage**'),
+    );
+    expect(
+      finalizeGateContractPrompt,
+      isNot(contains('- **Conformance coverage**')),
+    );
+    final parityAt = finalizeGateContractPrompt.indexOf(
+      '2.5. **Grader parity**',
+    );
+    final coverageAt = finalizeGateContractPrompt.indexOf('2.6. **Conformance');
+    final fixAt = finalizeGateContractPrompt.indexOf('3. **Fix every unmet');
+    expect(coverageAt, greaterThan(parityAt));
+    expect(fixAt, greaterThan(coverageAt));
+    // AC1: the checklist classes a conformance claim must quote.
+    expect(
+      finalizeGateContractPrompt,
+      contains('negative and combination checks'),
+    );
+    expect(finalizeGateContractPrompt, contains('incompatible'));
+    expect(finalizeGateContractPrompt, contains('mutually exclusive'));
+    expect(finalizeGateContractPrompt, contains('empty and corrupt inputs'));
+    expect(finalizeGateContractPrompt, contains('boundary values'));
+    expect(finalizeGateContractPrompt, contains('"must NOT work"'));
+    // A blanket "everything matches" is not a verified item.
+    expect(
+      finalizeGateContractPrompt,
+      contains('without such coverage is not verified'),
+    );
+  });
+
+  test('gh-1834 C2: the principle is taught abstractly; no benchmark or '
+      'task-specific names in the prompt', () {
+    // AC2 — happy-path agreement certifies nothing about rejection paths
+    // and combinations; the example is abstract (a port agreeing on every
+    // well-formed input), never a real benchmark/task/flag name.
+    expect(
+      finalizeGateContractPrompt,
+      contains('certifies nothing about rejection paths'),
+    );
+    expect(finalizeGateContractPrompt, contains('well-formed'));
+    for (final banned in [
+      'terminal-bench',
+      'harbor',
+      'compcert',
+      'crack-7z',
+      'TB-2',
+      'gh-18',
+    ]) {
+      expect(
+        finalizeGateContractPrompt,
+        isNot(contains(banned)),
+        reason: banned,
+      );
+    }
+  });
+
+  test('gh-1834 C3: tasks with no conformance claim see no gate change', () {
+    // The new requirement is CONDITIONAL — it binds only when the final
+    // claim includes conformance/parity. A task with no such claim keeps
+    // today's checklist shape (no new mandatory requirements).
+    expect(finalizeGateContractPrompt, contains('applies ONLY when'));
+  });
+
+  test('gh-1834 C4: the composed headless prompt carries the conformance '
+      'coverage step', () async {
+    final prompt = await promptOf(ApprovalMode.unattended, headlessRun: true);
+    expect(prompt, contains('2.6. **Conformance coverage**'));
+    expect(prompt, contains('negative and combination checks'));
